children.text:
.flex {
  display: flex;
  align-items: center;
  width: 100%;
  height: 100%;
}

.grid {
  display: grid;
  justify-items: center;
  align-items: center;
  width: 100%;
  height: 100%;
}

.container {
  border: 1px solid;
  position: relative;
  width: 100px;
  height: 100px;
  display: inline-block;
  margin-right: 5px;
}

.abs {
  width: 50px;
  height: 50px;
  position: absolute;
  background: purple;
}

.static-positioned-inline {
  left: auto;
  right: auto;
}

.static-positioned-block {
  top: auto;
  bottom: auto;
}

.positioned-inline {
  left: 0;
  right: 0;
}

.positioned-block {
  top: 0;
  bottom: 0;
}
